﻿// Funzioni specifiche per il menu

export function initMenu() {

    const footer = document.querySelector('footer');
    if (footer) {
        footer.style.display = 'none';
    }

    document.body.style.transition = "background-image 0.5s ease-in-out";
    document.body.style.backgroundImage = "url('/Img/BG_Img.webp')";
    document.body.style.backgroundSize = "cover";

    resizeForMenu();

    window.addEventListener('resize', function () {resizeForMenu()});
}

function resizeForMenu() {
    const divChildrenMenu = document.querySelectorAll('.child-menu');
    const divFatherMenu = document.querySelector('.father-menu');

    if (!divFatherMenu) {
        console.warn('Elemento .father-menu non trovato.');
        return;
    }

    let topForNext = 0;
    let totalFatherHeight = 0;

    if (divChildrenMenu.length > 0) {
        Array.from(divChildrenMenu).forEach(div => {
            totalFatherHeight += div.offsetHeight;
            div.style.height = div.offsetHeight + 'px';
            div.style.top = topForNext + 'px';
            topForNext += div.offsetHeight;
        });
    } else {
        console.warn('Nessun elemento trovato con la classe .child-menu.');
    }

    divFatherMenu.style.height = totalFatherHeight + 'px';
}
